using System.Text.RegularExpressions;
using SapAV.Core.Models;

namespace SapAV.Core.Yara;

/// <summary>
/// E2: the vendored third-party rules under <c>data/rules/third-party/</c> (a curated YARA-Forge subset, generated by
/// <c>update.ps1</c> from <c>curated-rules.txt</c>). The loader holds them to stricter meta rules than our own rules
/// (review E1/E3/E4 M2), see <see cref="Enforce"/>.
/// </summary>
public static partial class ThirdPartyRules
{
    /// <summary>The rule-file namespace prefix of the vendored rules (a path relative to the rules folder).</summary>
    public const string Folder = "third-party/";

    /// <summary>True for a rule file (YARA namespace) inside <see cref="Folder"/>.</summary>
    public static bool IsThirdParty(string file) =>
        file is not null && file.Replace('\\', '/').StartsWith(Folder, StringComparison.OrdinalIgnoreCase);

    /// <summary>
    /// True when the rule name says it detects malware (<c>MAL_</c>, <c>MALWARE_</c>, <c>Infostealer_</c>, <c>Stealer_</c>,
    /// <c>Trojan_</c>, <c>Crime_</c>, <c>RAT_</c>, <c>Backdoor_</c>, <c>Implant_</c>, <c>Ransom_</c>, <c>APT_</c> as a name token).
    /// Such a rule is never a hack tool or PUP.
    /// </summary>
    public static bool HasMalwareName(string identifier) => identifier is not null && MalwareMarker().IsMatch(identifier);

    /// <summary>True when the rule name says hack tool or PUP (<c>HKTL_</c>, <c>Hacktool_</c>, <c>Tool_</c>, <c>PUA_</c>, <c>PUP_</c>).</summary>
    public static bool HasUnwantedName(string identifier) => identifier is not null && UnwantedMarker().IsMatch(identifier);

    /// <summary>
    /// The stricter meta rules for a vendored rule, applied after the normal interpretation:
    /// <list type="bullet">
    /// <item>Both <c>verdict</c> and <c>category</c> meta must be present. If either is missing, nothing defaults silently:
    /// the rule is Suspicious (never the Malicious default of our own rules) and a warning names it.</item>
    /// <item>A rule whose name says malware (<see cref="HasMalwareName"/>) can't be a hack tool or PUP (that would make real
    /// malware never quarantined): it becomes Malware, Suspicious, with a warning.</item>
    /// </list>
    /// </summary>
    internal static (Verdict Verdict, ThreatCategory Category) Enforce(
        string file, string rule, bool hasVerdictMeta, bool hasCategoryMeta, Verdict verdict, ThreatCategory category,
        List<YaraRuleWarning> warnings)
    {
        if (HasMalwareName(rule) && ThreatCategories.IsPotentiallyUnwanted(category))
        {
            warnings.Add(new YaraRuleWarning(file, rule, YaraWarningKind.Category, category.ToString(),
                $"Third-party YARA rule {rule} ({file}) detects malware but is mapped to {category}; using Malware, Suspicious."));
            return (Verdict.Suspicious, ThreatCategory.Malware);
        }

        if (!hasVerdictMeta || !hasCategoryMeta)
        {
            string missing = !hasVerdictMeta && !hasCategoryMeta ? "verdict and category" : !hasVerdictMeta ? "verdict" : "category";
            warnings.Add(new YaraRuleWarning(file, rule, YaraWarningKind.Verdict, null,
                $"Third-party YARA rule {rule} ({file}) has no explicit {missing} meta; using Suspicious."));
            return (Verdict.Suspicious, category);
        }

        return (verdict, category);
    }

    [GeneratedRegex(@"(?:^|_)(?:MAL|MALWARE|MALWRE|INFOSTEALER|STEALER|TROJAN|CRIME|CRIMEWARE|RAT|BACKDOOR|IMPLANT|RANSOM|RANSOMWARE|APT)_",
        RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)]
    private static partial Regex MalwareMarker();

    [GeneratedRegex(@"(?:^|_)(?:HKTL|HACKTOOL|TOOL|PUA|PUP)_", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)]
    private static partial Regex UnwantedMarker();
}
